import type { Metadata } from "next";
import licenses from "@/data/licenses.json";

export const metadata: Metadata = { title: "Open-source licences" };

type Entry = { name: string; version: string; license: string; repository?: string | null };
const data = licenses as { generatedAt: string; count: number; packages: Entry[] };

/** Copyright Act 1957 / licence compliance: attribution for every production dependency (generated by scripts/licenses.mjs; the script fails the build on copyleft or unknown licences). */
export default function Licenses() {
  return (
    <article>
      <h1>Open-source licences</h1>
      <p className="meta">{data.count} production packages · list generated {data.generatedAt.slice(0, 10)} by <code>scripts/licenses.mjs</code>, which refuses GPL/AGPL/unknown licences so the site can never ship code it is not allowed to.</p>
      <p>CityCare also uses the <strong>Inter</strong> typeface (SIL Open Font License 1.1, self-hosted) and <strong>GSAP</strong> (Standard &ldquo;No Charge&rdquo; licence, permitted for this use). Full licence texts live in each package&apos;s <code>LICENSE</code> file in the source tree.</p>
      <table>
        <thead><tr><th>Package</th><th>Version</th><th>Licence</th></tr></thead>
        <tbody>
          {data.packages.map((p) => (
            <tr key={`${p.name}@${p.version}`}>
              <td>{p.repository ? <a href={p.repository} rel="noopener noreferrer" target="_blank">{p.name}</a> : p.name}</td>
              <td>{p.version}</td>
              <td>{p.license}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </article>
  );
}
